package com.ajpanel.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import android.text.*;import org.json.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 static final int PICK=41; ExecutorService io=Executors.newFixedThreadPool(2); android.content.SharedPreferences sp;
 ArrayList<Channel> all=new ArrayList<>(),shown=new ArrayList<>(); ArrayAdapter<Channel> adapter; LinearLayout body; TextView status; EditText m3u,name,host,user,pass,e2host,e2user,e2pass; Spinner group;
 int d(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 TextView t(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(0xffedf3f7);v.setPadding(d(12),d(10),d(12),d(10));return v;}
 Button b(String s,Runnable r){Button x=new Button(this);x.setText(s);x.setAllCaps(false);x.setOnClickListener(v->r.run());return x;}
 EditText f(String hint,String val){EditText x=new EditText(this);x.setSingleLine(true);x.setHint(hint);x.setText(val);x.setTextColor(-1);x.setHintTextColor(0xff9aa8b2);return x;}
 void page(String title){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff101820);TextView h=t("AJPanel Mobile  /  "+title,21);h.setBackgroundColor(0xff1b2b39);root.addView(h);ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setPadding(d(10),d(10),d(10),d(20));body.setOrientation(1);sc.addView(body);root.addView(sc);setContentView(root);}
 @Override public void onCreate(Bundle x){super.onCreate(x);sp=getSharedPreferences("ajp",0);home();}
 void home(){page("الرئيسية");body.addView(t("IPTV مستقل + إدارة Enigma2",17));body.addView(b("IPTV / القوائم والقنوات",()->iptv()));body.addView(b("أجهزة Enigma2 / OpenWebif",()->enigma()));body.addView(b("إعدادات التطبيق",()->settings()));body.addView(t("الإدارة المتقدمة للرسيفر ستضاف كوحدات فعلية بعد اختبار توافق OpenWebif وSSH/SFTP مع صورة الجهاز.",14));}
 void iptv(){page("IPTV");body.addView(t("إضافة قائمة M3U / M3U8",18));name=f("اسم القائمة","");m3u=f("الصق رابط M3U أو M3U8 هنا",sp.getString("last",""));body.addView(name);body.addView(m3u);body.addView(b("تحميل وحفظ القائمة",()->load(m3u.getText().toString().trim(),name.getText().toString().trim())));
 body.addView(b("استيراد ملف M3U من الهاتف",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK);}));
 body.addView(t("Xtream Codes",18));host=f("Server URL مثل http://host:port","");user=f("Username","");pass=f("Password","");body.addView(host);body.addView(user);body.addView(pass);body.addView(b("تحميل Xtream",()->{String h=host.getText().toString().trim().replaceAll("/$",""),u=user.getText().toString(),p=pass.getText().toString();if(h.isEmpty()||u.isEmpty()||p.isEmpty()){msg("أكمل بيانات الخادم.");return;}try{load(h+"/get.php?username="+enc(u)+"&password="+enc(p)+"&type=m3u_plus&output=ts","Xtream "+u);}catch(Exception e){msg(e.getMessage());}}));
 body.addView(t("المصادر المحفوظة",18));JSONArray a=sources();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;String u=o.optString("url"),n=o.optString("name");LinearLayout row=new LinearLayout(this);TextView label=t(n,14);row.addView(label,new LinearLayout.LayoutParams(0,-2,1));row.addView(b("فتح",()->load(u,n)));row.addView(b("حذف",()->{remove(u);iptv();}));body.addView(row);}
 status=t("لم يتم تحميل قائمة",14);body.addView(status);EditText search=f("بحث القنوات","");body.addView(search);group=new Spinner(this);body.addView(group);ListView lv=new ListView(this);adapter=new ArrayAdapter<Channel>(this,android.R.layout.simple_list_item_1,shown);lv.setAdapter(adapter);lv.setOnItemClickListener((p,v,pos,id)->{Intent it=new Intent(this,PlayerActivity.class);it.putExtra("name",shown.get(pos).name);it.putExtra("url",shown.get(pos).url);startActivity(it);});body.addView(lv,new LinearLayout.LayoutParams(-1,d(360)));
 search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){filter(s.toString(),selected());}public void afterTextChanged(Editable e){}});
 group.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){filter(search.getText().toString(),selected());}});
 body.addView(b("رجوع",()->home()));
 }
 String selected(){Object x=group.getSelectedItem();return x==null?"الكل":x.toString();}
 void load(String url,String nm){if(url.isEmpty()){msg("أدخل الرابط أولاً.");return;}status.setText("جار تحميل القائمة...");sp.edit().putString("last",url).apply();io.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(40000);c.setRequestProperty("User-Agent","AJPanel-Mobile/1.1");int code=c.getResponseCode();if(code<200||code>=300)throw new IOException("HTTP "+code);List<Channel> parsed=M3uParser.parse(c.getInputStream());c.disconnect();if(parsed.isEmpty())throw new IOException("لم يتم العثور على قنوات صالحة");save(url,nm.isEmpty()?new URL(url).getHost():nm);runOnUiThread(()->{all.clear();all.addAll(parsed);TreeSet<String> gs=new TreeSet<>();gs.add("الكل");for(Channel ch:all)if(!ch.group.isEmpty())gs.add(ch.group);ArrayAdapter<String> ga=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,new ArrayList<>(gs));group.setAdapter(ga);filter("","الكل");status.setText("تم تحميل "+all.size()+" قناة");});}catch(Exception e){runOnUiThread(()->status.setText("فشل التحميل: "+e.getMessage()));}});}
 void filter(String q,String g){shown.clear();for(Channel c:all)if((g.equals("الكل")||g.equals(c.group))&&(c.name.toLowerCase().contains(q.toLowerCase())||c.group.toLowerCase().contains(q.toLowerCase())))shown.add(c);if(adapter!=null)adapter.notifyDataSetChanged();}
 String enc(String s)throws Exception{return java.net.URLEncoder.encode(s,"UTF-8");}
 JSONArray sources(){try{return new JSONArray(sp.getString("sources","[]"));}catch(Exception e){return new JSONArray();}}
 void save(String u,String n){JSONArray a=sources(),b=new JSONArray();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&!u.equals(o.optString("url")))b.put(o);}try{JSONObject o=new JSONObject();o.put("url",u);o.put("name",n);b.put(o);}catch(Exception e){}sp.edit().putString("sources",b.toString()).apply();}
 void remove(String u){JSONArray a=sources(),b=new JSONArray();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&!u.equals(o.optString("url")))b.put(o);}sp.edit().putString("sources",b.toString()).apply();}
 @Override protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(r==PICK&&c==RESULT_OK&&data!=null){Uri u=data.getData();io.execute(()->{try{InputStream in=getContentResolver().openInputStream(u);List<Channel> p=M3uParser.parse(in);in.close();runOnUiThread(()->{all.clear();all.addAll(p);status.setText("تم استيراد "+p.size()+" قناة");filter("","الكل");});}catch(Exception e){runOnUiThread(()->msg(e.getMessage()));}});}}
 void enigma(){page("Enigma2");e2host=f("عنوان OpenWebif مثل http://192.168.1.20",sp.getString("e2",""));e2user=f("اسم المستخدم",sp.getString("eu","root"));e2pass=f("كلمة المرور",sp.getString("ep",""));body.addView(e2host);body.addView(e2user);body.addView(e2pass);TextView out=t("غير متصل",14);body.addView(out);body.addView(b("حفظ واختبار الاتصال",()->{String h=e2host.getText().toString().trim().replaceAll("/$",""),u=e2user.getText().toString(),p=e2pass.getText().toString();sp.edit().putString("e2",h).putString("eu",u).putString("ep",p).apply();io.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(h+"/web/about").openConnection();c.setConnectTimeout(7000);c.setReadTimeout(7000);if(!u.isEmpty())c.setRequestProperty("Authorization","Basic "+android.util.Base64.encodeToString((u+":"+p).getBytes("UTF-8"),android.util.Base64.NO_WRAP));int code=c.getResponseCode();String result="HTTP "+code; c.disconnect();runOnUiThread(()->out.setText(result));}catch(Exception e){runOnUiThread(()->out.setText("فشل الاتصال: "+e.getMessage()));}});}));body.addView(t("Bouquets وEPG وFiles وPlugins وSoftCam وBackup وSignal: تحتاج وحدات تنفيذ واختبار خاصة بكل صورة Enigma2، ولم يتم تفعيلها كأزرار وهمية.",14));body.addView(b("رجوع",()->home()));}
 void settings(){page("الإعدادات");CheckBox retry=new CheckBox(this);retry.setText("إعادة محاولة البث عند الانقطاع");retry.setTextColor(-1);retry.setChecked(sp.getBoolean("retry",true));retry.setOnCheckedChangeListener((v,x)->sp.edit().putBoolean("retry",x).apply());body.addView(retry);body.addView(t("Android 7+ • لا يحتاج Root أو Termux • ARM32/ARM64 حسب الجهاز",14));body.addView(b("مسح المصادر المحفوظة",()->new AlertDialog.Builder(this).setMessage("حذف كل مصادر IPTV؟").setNegativeButton("إلغاء",null).setPositiveButton("حذف",(x,y)->sp.edit().remove("sources").apply()).show()));body.addView(b("رجوع",()->home()));}
 void msg(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("حسناً",null).show();}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
